<?php
r_permission($user,$module);
$roleId=isset($_GET['role'])&&is_string($_GET['role'])?(int)$_GET['role']:0;
$applicationId=isset($_GET['application'])&&is_string($_GET['application'])?(int)$_GET['application']:0;
$selectedRole=$roleId?r_role($pdo,$roleId):null;
if($selectedRole&&$selectedRole['kind']!==$module){http_response_code(403);throw new DomainException('This role belongs to another department.');}
?>
<div class="pager"><?php if($module==='casting'):?><a class="text-link" href="<?= e(rtrim($config['base_url'],'/').'/production.php?kind=casting&section=auditions') ?>">Auditions and callbacks →</a><?php endif;?><a class="text-link" href="<?= e(rtrim($config['base_url'],'/').'/production.php?kind='.$module.'&section=evaluations') ?>">Private evaluations →</a></div>
<p>Publish adult-only opportunities, configure their forms and review applications. Final selection decisions are reserved for Super Admins.</p>
<?php if($applicationId):
$stmt=$pdo->prepare('SELECT a.*,r.title,r.kind,v.schema_json,v.role_snapshot FROM recruitment_applications a JOIN recruitment_roles r ON r.id=a.role_id JOIN recruitment_form_versions v ON v.role_id=a.role_id AND v.version=a.form_version WHERE a.id=? AND r.kind=?');$stmt->execute([$applicationId,$module]);$application=$stmt->fetch();if(!$application){http_response_code(404);throw new DomainException('Application not found in this department.');}
$schema=json_decode($application['schema_json'],true);$answers=json_decode($application['answers_json'],true);?>
<section class="panel"><h2><?= e($application['full_name']) ?></h2><p><?= e($application['reference']) ?> · <?= e($application['title']) ?> · Submitted form v<?= (int)$application['form_version'] ?></p><dl><dt>Email</dt><dd><?= e($application['email']) ?></dd><dt>Age / location</dt><dd><?= (int)$application['age'] ?> · <?= e($application['location']) ?></dd><dt>Availability</dt><dd><?= nl2br(e($application['availability'])) ?></dd><dt>Privacy notice acknowledged</dt><dd><?= e($application['acknowledged_at']) ?> UTC · Notice <?= e($application['notice_version']) ?></dd><dt>Retention review due</dt><dd><?= e($application['retention_due_at']??($application['outcome']==='selected'?'Selected production record: separate contractual retention policy.':'Not determined; outcome or recruitment closure pending.')) ?></dd></dl>
<?php if($application['duplicate_flag']):?><p class="notice">Possible duplicate application for this role. Review it; no automatic rejection was made.</p><?php endif;?>
<h3>Submitted answers</h3><dl><?php foreach($schema as $question): if($question['type']==='file'){continue;}?><dt><?= e($question['label']) ?></dt><dd><?= nl2br(e($answers[$question['id']]??'')) ?></dd><?php endforeach;?></dl>
<?php $stmt=$pdo->prepare('SELECT id,question_id,mime,size_bytes FROM recruitment_attachments WHERE application_id=?');$stmt->execute([$applicationId]);foreach($stmt as $attachment):?><p><a class="text-link" href="<?= e(rtrim($config['base_url'],'/').'/attachment.php?id='.$attachment['id']) ?>">Download <?= e(array_column($schema,'label','id')[$attachment['question_id']]??'Attachment') ?> · <?= e($attachment['mime']) ?> · <?= (int)$attachment['size_bytes'] ?> bytes</a></p><?php endforeach;?>
<details><summary>Original published opportunity and privacy notice</summary><dl><?php foreach(json_decode($application['role_snapshot'],true) as $key=>$value):?><dt><?= e(ucwords(str_replace('_',' ',$key))) ?></dt><dd><?= e((string)$value) ?></dd><?php endforeach;?></dl><p><?= nl2br(e($application['privacy_notice'])) ?></p></details></section>
<section class="panel"><h2>Recruitment review</h2><form method="post" action="<?= e(admin_url($module)) ?>"><?php csrf_input();?><input type="hidden" name="action" value="application_update"><input type="hidden" name="application_id" value="<?= (int)$applicationId ?>"><label for="public_status">Applicant-visible status</label><select id="public_status" name="public_status"><?php foreach(R_STATUSES as $status):?><option<?= $application['public_status']===$status?' selected':'' ?>><?= e($status) ?></option><?php endforeach;?></select><label for="outcome">Private final selection decision</label><select id="outcome" name="outcome"<?= $user['role']!=='super_admin'?' disabled':'' ?>><?php foreach(['pending'=>'Pending','selected'=>'Selected','not_selected'=>'Not selected'] as $value=>$label):?><option value="<?= e($value) ?>"<?= $application['outcome']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select><?php if($user['role']!=='super_admin'):?><input type="hidden" name="outcome" value="<?= e($application['outcome']) ?>"><?php endif;?><label for="private_note">Private review note (optional)</label><textarea id="private_note" name="private_note" rows="4" maxlength="4000"></textarea><p class="field-help">Notes and final decisions are never shown in tracking. Selection does not publish an actor reveal. Open Auditions and callbacks to arrange a session. Recommendations and scheduling do not change final decisions.</p><button class="button">Save review</button></form></section>
<section class="panel"><h2>Private review history</h2><?php $stmt=$pdo->prepare('SELECT e.*,u.username FROM recruitment_events e LEFT JOIN administrators u ON u.id=e.actor_id WHERE application_id=? ORDER BY e.id DESC LIMIT 50');$stmt->execute([$applicationId]);foreach($stmt as $event):?><article><h3><?= e($event['public_status']) ?></h3><p><?= e($event['username']??'Removed administrator') ?> · <?= e($event['created_at']) ?> UTC · <?= e($event['outcome']) ?></p><p><?= nl2br(e($event['private_note'])) ?></p></article><?php endforeach;?></section>
<section class="panel"><h2>Transactional delivery log</h2><?php $stmt=$pdo->prepare('SELECT purpose,delivery_status,result_code,created_at FROM recruitment_delivery_log WHERE application_id=? ORDER BY id DESC LIMIT 20');$stmt->execute([$applicationId]);foreach($stmt as $delivery):?><p><?= e($delivery['created_at'].' · '.$delivery['purpose'].' · '.$delivery['delivery_status'].' · '.$delivery['result_code']) ?></p><?php endforeach;?><p class="field-help">Provider acceptance is not proof of inbox delivery. If confirmation failed, an authorized reviewer may contact the applicant manually through the recorded email address. Never disclose tracking codes to an unverified requester.</p></section>
<?php else: ?>
<div class="panel"><h2>Opportunities</h2><a class="text-link" href="<?= e(admin_url($module).'&new=1') ?>">Create a new opportunity →</a><?php $stmt=$pdo->prepare('SELECT id,title,state,deadline,published_version FROM recruitment_roles WHERE kind=? ORDER BY id DESC LIMIT 100');$stmt->execute([$module]);foreach($stmt as $item):?><p><a class="text-link" href="<?= e(admin_url($module).'&role='.$item['id']) ?>"><?= e($item['title']) ?></a> · <?= e($item['state']) ?> · v<?= (int)$item['published_version'] ?> · deadline <?= e($item['deadline']) ?> UTC</p><?php endforeach;?></div>
<?php if($selectedRole||isset($_GET['new'])): $draft=$selectedRole?json_decode($selectedRole['draft_schema'],true):[]; $preview=isset($_GET['preview']); ?>
<?php if($preview):?><section class="panel"><h2>Draft form preview</h2><p><?= e($selectedRole['title']??'New opportunity') ?> · Preview only; this form cannot submit an application.</p><p>Name, email, adult age, location, availability, mandatory eligibility and privacy acknowledgment are always included.</p><?php $schema=$draft;require __DIR__.'/recruitment-fields.php';?><a class="text-link" href="<?= e(admin_url($module).'&role='.$roleId) ?>">Return to editor</a></section><?php else:?>
<section class="panel"><h2><?= $selectedRole?'Edit draft':'New opportunity' ?></h2><p class="field-help">Saving pauses recruitment for this role. Publish again to create a new immutable version. Previous submissions keep their original form and role information.</p><form method="post" action="<?= e(admin_url($module)) ?>"><?php csrf_input();?><input type="hidden" name="action" value="role_save"><input type="hidden" name="role_id" value="<?= (int)$roleId ?>">
<?php foreach(['title'=>['Role title',150],'location'=>['Location requirement',200],'availability'=>['Required availability',300]] as $key=>[$label,$limit]):?><label for="<?= e($key) ?>"><?= e($label) ?></label><input id="<?= e($key) ?>" name="<?= e($key) ?>" maxlength="<?= $limit ?>" value="<?= e($selectedRole[$key]??'') ?>" required><?php endforeach;?>
<?php foreach(['description'=>['Spoiler-free description',6000,true],'mandatory_requirements'=>['Mandatory eligibility requirements',4000,true],'preferences'=>['Preferences (not mandatory)',4000,false]] as $key=>[$label,$limit,$required]):?><label for="<?= e($key) ?>"><?= e($label) ?></label><textarea id="<?= e($key) ?>" name="<?= e($key) ?>" rows="4" maxlength="<?= $limit ?>"<?= $required?' required':'' ?>><?= e($selectedRole[$key]??'') ?></textarea><?php endforeach;?>
<label for="age_min">Minimum age (18 or older)</label><input id="age_min" name="age_min" type="number" min="18" max="100" value="<?= (int)($selectedRole['age_min']??18) ?>" required><label for="age_max">Maximum age (optional)</label><input id="age_max" name="age_max" type="number" min="18" max="100" value="<?= e((string)($selectedRole['age_max']??'')) ?>"><label for="deadline">Application deadline (UTC)</label><input id="deadline" name="deadline" type="datetime-local" value="<?= e(isset($selectedRole['deadline'])?str_replace(' ','T',substr($selectedRole['deadline'],0,16)):'') ?>" required>
<h3>Custom questions</h3><p class="field-help">Choose the field type, required status, order and selection choices. Use external links for large audition videos. At most 20 questions, including three small file questions. Three blank rows allow adding questions without JavaScript.</p><div id="question-list"><?php foreach([...$draft,['id'=>'q'.bin2hex(random_bytes(5))],['id'=>'q'.bin2hex(random_bytes(5))],['id'=>'q'.bin2hex(random_bytes(5))]] as $index=>$question):$key=$question['id'];require __DIR__.'/recruitment-question.php';endforeach;?></div><button class="sign-out" type="button" id="add-question" hidden>Add another question</button><button class="button" type="submit">Save role and form draft</button></form></section>
<?php endif;?>
<?php if($selectedRole):?><section class="panel"><h2>Publication controls</h2><a class="text-link" href="<?= e(admin_url($module).'&role='.$roleId.'&preview=1') ?>">Preview saved draft →</a><p><?= e(implode(' ',r_readiness($pdo,$draft))?:'Global readiness checks passed. Review the saved draft before publishing.') ?></p><form method="post" action="<?= e(admin_url($module)) ?>"><?php csrf_input();?><input type="hidden" name="role_id" value="<?= $roleId ?>"><button class="button" name="action" value="role_publish">Publish new version and open role</button> <button class="sign-out" name="action" value="role_close">Close role</button></form><h3>Reusable forms</h3><form method="post" action="<?= e(admin_url($module)) ?>"><?php csrf_input();?><input type="hidden" name="role_id" value="<?= $roleId ?>"><input type="hidden" name="action" value="template_save"><label for="template_name">Save this draft as a template</label><input id="template_name" name="template_name" maxlength="120" required><button class="button">Save template</button></form><form method="post" action="<?= e(admin_url($module)) ?>"><?php csrf_input();?><input type="hidden" name="role_id" value="<?= $roleId ?>"><input type="hidden" name="action" value="template_apply"><label for="template_id">Copy a department template into this draft</label><select id="template_id" name="template_id" required><option value="">Choose template</option><?php $stmt=$pdo->prepare('SELECT id,name FROM recruitment_form_templates WHERE kind=? ORDER BY id DESC LIMIT 100');$stmt->execute([$module]);foreach($stmt as $template):?><option value="<?= (int)$template['id'] ?>"><?= e($template['name']) ?></option><?php endforeach;?></select><button class="button">Apply template</button></form><h3>Published version history</h3><?php $stmt=$pdo->prepare('SELECT version,published_at FROM recruitment_form_versions WHERE role_id=? ORDER BY version DESC LIMIT 50');$stmt->execute([$roleId]);foreach($stmt as $version):?><p>Version <?= (int)$version['version'] ?> · <?= e($version['published_at']) ?> UTC</p><?php endforeach;?></section><?php endif;?>
<?php endif;?>
<section class="panel"><h2>Applications</h2><form method="get" action="<?= e(rtrim($config['base_url'],'/').'/admin.php') ?>"><input type="hidden" name="module" value="<?= e($module) ?>"><label for="filter_status">Filter public status</label><select id="filter_status" name="status"><option value="">All statuses</option><?php foreach(R_STATUSES as $status):?><option<?= ($_GET['status']??'')===$status?' selected':'' ?>><?= e($status) ?></option><?php endforeach;?></select><button class="button">Filter applications</button></form>
<?php $filter=isset($_GET['status'])&&is_string($_GET['status'])&&in_array($_GET['status'],R_STATUSES,true)?$_GET['status']:'';$number=isset($_GET['p'])&&is_string($_GET['p'])?max(1,min(100000,(int)$_GET['p'])):1;$stmt=$pdo->prepare('SELECT a.id,a.reference,a.full_name,a.public_status,a.duplicate_flag,r.title FROM recruitment_applications a JOIN recruitment_roles r ON r.id=a.role_id WHERE r.kind=?'.($filter!==''?' AND a.public_status=?':'').' ORDER BY a.id DESC LIMIT 21 OFFSET '.(($number-1)*20));$stmt->execute($filter!==''?[$module,$filter]:[$module]);$items=$stmt->fetchAll();$more=count($items)>20;foreach(array_slice($items,0,20) as $item):?><p><a class="text-link" href="<?= e(admin_url($module).'&application='.$item['id']) ?>"><?= e($item['full_name'].' · '.$item['title']) ?></a><br><?= e($item['reference'].' · '.$item['public_status']) ?><?= $item['duplicate_flag']?' · Possible duplicate':'' ?></p><?php endforeach;?><?php if(!$items):?><p>No applications match this view.</p><?php endif;?><div class="pager"><?php if($number>1):?><a href="<?= e(admin_url($module).'&status='.rawurlencode($filter).'&p='.($number-1)) ?>">← Previous</a><?php endif;?><?php if($more):?><a href="<?= e(admin_url($module).'&status='.rawurlencode($filter).'&p='.($number+1)) ?>">Next →</a><?php endif;?></div></section>
<?php endif;?>
